CREATE OR REPLACE FUNCTION public.get_vault_secret(p_secret_name text) RETURNS text AS $$$ DECLARE v_secret text; BEGIN SELECT TRIM(decrypted_secret) INTO v_secret FROM vault.decrypted_secrets WHERE lower(name) = lower(p_secret_name) OR lower(name) = lower('supabase_' || p_secret_name) LIMIT 1; RETURN v_secret; EXCEPTION WHEN OTHERS THEN RETURN NULL; END; $$$ LANGUAGE plpgsql SECURITY DEFINER; CREATE OR REPLACE FUNCTION public.trigger_push_on_notification_insert() RETURNS trigger AS $$$ DECLARE v_supabase_url TEXT; v_auth_key TEXT; BEGIN v_supabase_url := 'https://mecutwhreywjwstirpka.supabase.co'; v_auth_key := public.get_vault_secret('SUPABASE_SERVICE_ROLE_KEY'); IF v_auth_key IS NULL OR v_auth_key = '' THEN v_auth_key := public.get_vault_secret('SERVICE_ROLE_KEY'); END IF; IF v_auth_key IS NULL OR v_auth_key = '' THEN v_auth_key := public.get_vault_secret('service_role_key'); END IF; IF v_auth_key IS NOT NULL AND v_auth_key <> '' THEN BEGIN PERFORM net.http_post(url := v_supabase_url || '/functions/v1/send-push-notification', headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_auth_key, 'apikey', v_auth_key), body := jsonb_build_object('user_id', NEW.user_id, 'title', NEW.title, 'body', NEW.message, 'url', COALESCE(NEW.metadata->>'url', '/'), 'type', NEW.type, 'notification_id', NEW.id)); EXCEPTION WHEN OTHERS THEN INSERT INTO public.push_delivery_log (notification_id, user_id, error_message) VALUES (NEW.id, NEW.user_id, SQLERRM); END; ELSE INSERT INTO public.push_delivery_log (notification_id, user_id, error_message) VALUES (NEW.id, NEW.user_id, 'No valid service_role_key found in Supabase Vault'); END IF; RETURN NEW; END; $$$ LANGUAGE plpgsql SECURITY DEFINER;